    const changed = vi.fn()
    agentAcknowledgementService.addEventListener(PROJECT_ACKNOWLEDGEMENT_EVENT, changed)
    const context = { kind: 'project' as const }
    const reference = 'design/activity/project.json#conversation=project-agent'
